<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue'
const days=ref(30),status=ref('ALL'),page=ref(1),data=ref<any>(),busy=ref(false),error=ref('');let active:AbortController|undefined
const MOVIE_PREVIEW_LIMIT=30,expandedRows=ref<Record<string,boolean>>({})
const labels:Record<string,string>={ALL:'全部状态',PREVIEW:'待确认',QUEUED:'排队中',PENDING:'待执行',RUNNING:'执行中',SUCCEEDED:'完成',PARTIAL:'部分完成',FAILED:'失败',NEEDS_REVIEW:'提交待核验',CANCELLED:'已取消',EXPIRED:'已过期',NO_RECEIPT:'未查到数据库回执'}
const statusOptions=Object.entries(labels).filter(([key])=>key!=='NO_RECEIPT')
const countNames:Record<string,string>={movies:'影片',inserted:'新增',updated:'更新',skipped:'跳过',errors:'错误',review:'待核验',total:'合计',source_movies:'来源影片',people:'人物',credits:'演职员关系',person_assets:'人物媒体',movie_assets:'影片媒体',movie_source_records:'来源记录',movie_external_ids:'外部身份',genres:'类型',movie_genres:'影片类型关系'}
const when=(v:string)=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—'
function visibleMovies(item:any){const list=Array.isArray(item?.movies)?item.movies:[];return expandedRows.value[item.id]?list:list.slice(0,MOVIE_PREVIEW_LIMIT)}
async function refresh(reset=false){if(reset)page.value=1;active?.abort();const c=new AbortController();active=c;busy.value=true;error.value=''
 try{const params=new URLSearchParams({days:String(days.value),page:String(page.value),status:status.value});const r=await fetch('/api/admin/import-audit?'+params,{credentials:'same-origin',signal:AbortSignal.any([c.signal,AbortSignal.timeout(20000)])});let body:any=null;try{body=await r.json()}catch{body=null};if(!r.ok)throw new Error(r.status===401?'登录已失效，请重新登录。':r.status===403?'需要管理员权限。':(r.status===503||body?.code==='DATA_UNAVAILABLE')?'导入审计统计来源暂时不可用（DATA_UNAVAILABLE），请稍后重试。':'导入审计暂时无法读取，请重试。');if(active===c&&!c.signal.aborted){data.value=body?.data;expandedRows.value={}}}
 catch(e){if(active===c&&!c.signal.aborted&&(e as Error).name!=='AbortError')error.value=(e as Error).message}finally{if(active===c)busy.value=false}}
async function move(n:number){page.value+=n;await refresh()}
onMounted(()=>refresh());onBeforeUnmount(()=>active?.abort());defineExpose({refresh})
</script>
<template><section class="import-audit" aria-labelledby="import-audit-title"><header><h2 id="import-audit-title">导入任务审计</h2><div><label for="audit-days">时间窗口</label><select id="audit-days" v-model="days" @change="refresh(true)"><option :value="7">近 7 天</option><option :value="30">近 30 天</option><option :value="90">近 90 天</option></select><label for="audit-status">任务状态</label><select id="audit-status" v-model="status" @change="refresh(true)"><option v-for="[key,label] in statusOptions" :key="key" :value="key">{{label}}</option></select><button :disabled="busy" @click="refresh()">刷新审计</button></div></header>
 <p>合并统一导入任务与历史数据库批次，可核对操作者、影片范围、任务状态和数据库提交回执。历史批次没有记录的操作者保持未知。</p><p v-if="error" role="alert" class="error">{{error}}<span v-if="data">（已保留上一份可用快照）</span> <button type="button" :disabled="busy" @click="refresh()">重试</button></p><p v-if="busy&&!data" role="status">正在读取导入审计…</p>
 <template v-if="data"><p>共 {{data.total.toLocaleString()}} 条 · 第 {{data.page}} / {{data.pages}} 页<span v-if="busy"> · 正在更新…</span></p><p v-if="data.unreadable_task_records" role="alert">{{data.unreadable_task_records}} 份任务状态记录无法完整读取；已保留可查询的数据库批次，请运维核对。</p>
 <p v-if="!data.items.length">当前时间和状态下没有导入记录。</p><div v-else class="audit-table"><table><thead><tr><th>时间 / 对象</th><th>操作者</th><th>来源 / 范围</th><th>任务状态</th><th>数据库回执</th><th>结果</th></tr></thead><tbody><tr v-for="item in data.items" :key="item.id"><td>{{when(item.at)}}<small>{{item.job_id?'任务 '+item.job_id:'历史批次 #'+item.batch_id}}</small></td><td>{{item.actor}}</td><td>{{item.source}} · {{item.movie_count==null?'数量见批次指标':item.movie_count+' 部'}}<details v-if="item.movies.length"><summary>查看影片范围（{{item.movies.length}}）</summary><p v-for="(m,i) in visibleMovies(item)" :key="i">{{m.title}} · 内部 {{m.movie_id??'新建'}} · TMDB {{m.tmdb_id}}</p><button v-if="item.movies.length>MOVIE_PREVIEW_LIMIT&&!expandedRows[item.id]" type="button" @click="expandedRows[item.id]=true">展开全部 {{item.movies.length}} 部</button></details></td><td>{{labels[item.status]||item.status}}<small v-if="item.error_code">{{item.error_code}}</small></td><td>{{labels[item.commit_state]||item.commit_state}}<small v-if="item.batch_id">批次 #{{item.batch_id}}</small></td><td><span v-if="!Object.keys(item.counts).length">暂无计数</span><span v-for="(value,key) in item.counts" :key="key" class="count">{{countNames[key]||key}}：{{value}}</span></td></tr></tbody></table></div>
 <nav aria-label="导入审计分页"><button :disabled="busy||data.page<=1" @click="move(-1)">上一页</button><span>{{data.page}} / {{data.pages}}</span><button :disabled="busy||data.page>=data.pages" @click="move(1)">下一页</button></nav></template>
 <p class="note">展示当前任务状态及批次记录，不代表每次按钮操作的完整历史；文件任务与提交批次去重。仅展示审计摘要，不返回来源载荷、密钥或备份路径。</p>
</section></template>
<style scoped>
.import-audit{color:var(--mi-text-soft);margin-bottom:28px;padding-bottom:26px;border-bottom:1px solid var(--mi-border)}.import-audit header,.import-audit header div,.import-audit nav{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.import-audit h2{font-family:var(--serif);font-size:18px;font-weight:500;margin:0;color:var(--mi-text-ivory)}.import-audit p{max-width:85ch;color:var(--mi-text-secondary);font-size:13.5px;line-height:1.8}.import-audit label{font-size:12.5px;color:var(--mi-text-secondary)}.import-audit select{font:inherit;font-size:12.5px;color:var(--mi-text);background:var(--mi-input-bg);border:1px solid var(--mi-border-strong);border-radius:8px;padding:7px 10px}.import-audit button{font:inherit;font-size:12.5px;color:var(--mi-text);background:transparent;border:1px solid var(--mi-border-strong);border-radius:8px;padding:7px 12px;cursor:pointer;transition:background-color .18s ease,border-color .18s ease}.import-audit button:hover:not(:disabled){background:var(--mi-surface-hover);border-color:var(--mi-accent-border);color:var(--mi-text)}.import-audit button:disabled{opacity:.5;cursor:default}.audit-table{overflow:auto;border:1px solid var(--mi-border);border-radius:10px;scrollbar-color:var(--mi-scroll-thumb) var(--mi-scroll-track)}table{width:100%;min-width:940px;border-collapse:collapse;font-size:13px;font-variant-numeric:tabular-nums}th,td{text-align:left;padding:10px 12px;border-bottom:1px solid var(--mi-border-subtle);vertical-align:top}thead th{color:var(--mi-text-secondary);background:var(--mi-surface-raised);font-size:11px;font-weight:500}small{display:block;max-width:32ch;overflow-wrap:anywhere;color:var(--mi-text-muted);font-size:11.5px;margin-top:5px}details{margin-top:10px}summary{cursor:pointer;color:var(--mi-accent-text)}details p{min-width:200px}.count{display:block;font-size:12px;color:var(--mi-text-secondary)}.import-audit nav{justify-content:flex-end;margin-top:18px;font-size:13px;color:var(--mi-text-secondary)}.import-audit .error{color:var(--mi-negative)}.import-audit :focus-visible{outline:2px solid var(--mi-accent);outline-offset:2px}
</style>
